[Form]
public class AVAGroupBalance extends FormRun
{
    CredManCreditLimitId					groupTableId;
    CredManCreditLimitCustGroup				creditLimitCustGroup;
    CredManCreditLimitCustGroupLine			creditLimitCustGroupLine;
    CustTable								custTableCaller;
    //private CredManBlockExclusionValueType	thresholdType;
    CredManParameters						credManParameters = CredManParameters::avaFindCredManParameters();

}

public void init()
{

    super();

    if(element.args() && element.args().record() && credManParameters.CrossCompanyCreditCheck)
    {
        switch(element.args().dataset())
        {
            case tableNum(CredManCreditLimitCustGroup):
                creditLimitCustGroup = element.args().record();
                groupTableId = creditLimitCustGroup.CreditLimitId;
                break;

            case tableNum(CustTable):
                custTableCaller = element.args().record();

                select firstonly creditLimitCustGroupLine
                    where creditLimitCustGroupLine.custAccount == custTableCaller.AccountNum
                       && creditLimitCustGroupLine.Company == custTableCaller.DataAreaId
                join creditLimitCustGroup
                    where creditLimitCustGroup.RecId == creditLimitCustGroupLine.CreditLimitCustGroup;

                groupTableId = creditLimitCustGroup.CreditLimitId;
                break;

            default:
                throw error(error::missingFormActiveBuffer(element.design().caption()));
        }

        if( !groupTableId)
        {
            throw error("@AVAFCM:CreditLimitError");
        }
    }
    else
    {
        throw error(error::missingFormActiveBuffer(element.design().caption()));
    }

}

/// <summary>
/// update the temp table records
/// </summary>
public void updateBalance()
{
    tmpCustVendTrans          tmpCustVendTrans;
    tmpCustVendTrans          tmpCustVendTransHelper;
    AmountMST                 totalAmountMST;
    CustCreditMaxCur		  limitAmountMST;
    AmountMst                 totalNetEstimatedAmount;
    CredManBlockExclusionRule CredManBlockExclusionRule;
    AVAFCMGroupTable		  groupTable;
    //CredManCreditLimitCustGroupLine     CRLCustGroupLine;
    //CredManCreditLimitCustGroup         CRLCustGroup;

    //If form is opened for a customer
    if (custTableCaller)
    {
        //tmpCustVendTrans = AVAFCMGroupTable::getBalanceTmpTableByGroupForBalanceFormByCust(groupTableId, custTableCaller.AccountNum);
        tmpCustVendTrans = AVAFCMGroupTableHelper::getBalanceTmpTableByGroupForBalanceFormByCust(groupTableId, custTableCaller.AccountNum);
    }
    //If form is opened for a credit limit group
    else
    {
        //tmpCustVendTrans = AVAFCMGroupTable::getBalanceTmpTableByGroupForBalanceForm(groupTableId);
        tmpCustVendTrans = AVAFCMGroupTableHelper::getBalanceTmpTableByGroupForBalanceForm(groupTableId);
    }

    tmpCustVendTransHelper.setTmpData(tmpCustVendTrans);

    //Accounting balance logic is already handled in above code
    if (!custTableCaller)
    {
        while select sum(AmountMST), sum(AmountCur), sum(AVAFPLNetEstimatedAmount), sum(AVAFPLNetEstimatedInvoicedAmount) from tmpCustVendTransHelper
        {
            totalAmountMST          += tmpCustVendTransHelper.amountMST;
            totalNetEstimatedAmount += tmpCustVendTransHelper.AVAFPLNetEstimatedAmount;
        }

        // Total im standard currency
        tmpCustVendTrans.CurrencyCode   = CompanyInfoHelper::standardCurrency();
        tmpCustVendTrans.AmountMst      = totalAmountMST;
        tmpCustVendTrans.AmountCur      = 0;
        tmpCustVendTrans.TotalAmountMst = 0;
        tmpCustVendTrans.AVAFPLNetEstimatedAmount = totalNetEstimatedAmount;
        tmpCustVendTrans.Txt            = "@SYS94871";
        tmpCustVendTrans.insert();
    }
    else
    {
        select sum(AmountMST), sum(AVAFPLNetEstimatedAmount), sum(AVAFPLNetEstimatedInvoicedAmount), sum(AmountCur) from tmpCustVendTransHelper
            where tmpCustVendTransHelper.Txt == "@AVAFCM:AccountBalanceCurrentCustomer"
            || tmpCustVendTransHelper.Txt == "@AVAFCM:AccountBalanaceOtherCustomer";

        totalAmountMST          = tmpCustVendTransHelper.amountMST;
        totalNetEstimatedAmount = tmpCustVendTransHelper.AVAFPLNetEstimatedAmount;
    }

    limitAmountMST = groupTable.showLimitAmountMST(groupTableId);

    tmpCustVendTrans.CurrencyCode   = CompanyInfoHelper::standardCurrency();
    tmpCustVendTrans.AmountMst      = limitAmountMST;
    tmpCustVendTrans.AmountCur      = 0;
    tmpCustVendTrans.TotalAmountMst = 0;
    tmpCustVendTrans.AVAFPLNetEstimatedAmount = limitAmountMST;
    tmpCustVendTrans.Txt            = "@SYS1532";
    tmpCustVendTrans.insert();

    if (custTableCaller.AccountNum)
    {
        select firstonly CredManBlockExclusionRule
            where CredManBlockExclusionRule.RuleId == CredManBlockExclusionRuleType::ExceedCreditLimit
            && CredManBlockExclusionRule.TableGroupAll == TableGroupAll::Table
            && CredManBlockExclusionRule.CustRelation == custTableCaller.AccountNum;
    }

    /*if (!CredManBlockExclusionRule && !custTableCaller.AVAIsCreditLimitRiscDebtor())
    {
        select firstonly CRLCustGroupLine where CRLCustGroupLine.CustAccount == custTableCaller.AccountNum
            join CRLCustGroup where CRLCustGroup.RecId == CRLCustGroupLine.CreditLimitCustGroup
                                 && CRLCustGroup.AVACompanyId == curExt();
        select firstonly CredManBlockExclusionRule
            where CredManBlockExclusionRule.CustRelation == CRLCustGroup.AVARiscDebtor;
    }*/

    if (!CredManBlockExclusionRule && groupTableId)
    {
        select firstonly CredManBlockExclusionRule
            where CredManBlockExclusionRule.RuleId == CredManBlockExclusionRuleType::ExceedCreditLimit 
            && CredManBlockExclusionRule.TableGroupAll == TableGroupAll::GroupId 
            && CredManBlockExclusionRule.CustRelation == groupTableId;
    }

    if (!CredManBlockExclusionRule)
    {
        select firstonly CredManBlockExclusionRule
                        where CredManBlockExclusionRule.TableGroupAll == TableGroupAll::All
                           && CredManBlockExclusionRule.RuleId == CredManBlockExclusionRuleType::ExceedCreditLimit;
    }

    CredManCreditLimitThreshold threshold =  CredManBlockExclusionRule.CreditLimitThreshold;
    //thresholdType = CredManBlockExclusionValueType::Percent;

    tmpCustVendTrans.CurrencyCode   = CompanyInfoHelper::standardCurrency();
    tmpCustVendTrans.AmountMst      = limitAmountMST * (threshold/100);
    tmpCustVendTrans.AmountCur      = 0;
    tmpCustVendTrans.TotalAmountMst = 0;
    tmpCustVendTrans.AVAFPLNetEstimatedAmount = limitAmountMST * (threshold/100);
    tmpCustVendTrans.Txt            = "@AVAFCM:CreditLimitThreshold";
    tmpCustVendTrans.insert();

    tmpCustVendTrans.CurrencyCode   = CompanyInfoHelper::standardCurrency();
    if (threshold)
    {
        tmpCustVendTrans.AmountMst      = limitAmountMST * (threshold/100) - totalAmountMST;
    }
    else
    {
        tmpCustVendTrans.AmountMst      = limitAmountMST - totalAmountMST;
    }
    tmpCustVendTrans.AmountCur      = 0;
    tmpCustVendTrans.TotalAmountMst = 0;
    if (threshold)
    {
        tmpCustVendTrans.AVAFPLNetEstimatedAmount = limitAmountMST * (threshold/100) - totalNetEstimatedAmount;
    }
    else
    {
        tmpCustVendTrans.AVAFPLNetEstimatedAmount = limitAmountMST - totalNetEstimatedAmount;
    }
    tmpCustVendTrans.Txt            = "@SYS94872";
    tmpCustVendTrans.insert();

    delete_from tmpCustVendTrans where tmpCustVendTrans.Txt == "@AVAFCM:BalanceOtherCustomers";

    GroupBalanceCurrency.setTmpData(tmpCustVendTrans);
}

/// <summary>
/// Update the form design
/// </summary>
public void updateDesign()
{
    //Show/hide Balance and Estimated net amount columns based on parameter
    if (CustParameters::find().AVAFCMCalcBalance == AVAFCMCalcBalance::Gross)
    {
        GroupBalanceCurrency_ds.object(fieldNum(TmpCustVendTrans, AVAFPLNetEstimatedAmount)).visible(false);
        GroupBalanceCurrency_ds.object(fieldNum(TmpCustVendTrans, AmountMST)).visible(true);
    }
    else
    {
        GroupBalanceCurrency_ds.object(fieldNum(TmpCustVendTrans, AVAFPLNetEstimatedAmount)).visible(true);
        GroupBalanceCurrency_ds.object(fieldNum(TmpCustVendTrans, AmountMST)).visible(false);
    }
}

/// <summary>
///     Populates the temp table and updates the design
/// </summary>
public void executeQuery()
{
    if (credManParameters.CrossCompanyCreditCheck)
    {
        element.updateBalance();
        element.updateDesign();
    }
    //QueryBuildRange     qbr = SysQuery::findOrCreateRange(this.queryBuildDataSource(), fieldNum(tmpcustvendtrans, Txt));
    //qbr.value(SysQuery::valueNot("@AVAFCM:AccountBalanaceOtherCustomer"));

    super();
}
